  // Código ilustrativo: agregado idempotente (conjunto de event_id en vez de contador).
  const VELOCITY_PY = `# Feature "transacciones de la tarjeta en los últimos 10 min" sin doble conteo.
# Estado = conjunto de event_id por tarjeta (ZSET de Redis con el event time como score).
# Reprocesar el mismo evento no cambia nada: ZADD con el mismo miembro es idempotente.
WINDOW_S = 600

def on_event(r, ev):
    key = f"txn10m:{ev['card_id']}"
    r.zadd(key, {ev["event_id"]: ev["event_ts"]})              # conjunto, no +1
    r.zremrangebyscore(key, "-inf", ev["event_ts"] - WINDOW_S)  # saca lo que salió de la ventana
    r.expire(key, WINDOW_S * 2)                                 # una tarjeta inactiva no ocupa memoria
    count = r.zcard(key)
    r.hset(f"features:{ev['card_id']}", "txn_count_10m", count) # upsert: mismo valor al reprocesar
`;

